INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('waking', 'time', '«الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ»', 'Alle lof zij Allaah, Die ons het leven heeft teruggegeven nadat Hij ons had doen sterven, en tot Hem is de opwekking.', 'All praise is for Allaah who gave us life after having caused us to die, and to Him is the resurrection.', 'يقوله أول ما يفتح عينيه من نومه، مستحضرا أن النوم موتة صغرى وأن اليقظة بعث مصغر يذكّر بالنشور.', 'Zegt men zodra men de ogen opent, zich bewust dat slaap een kleine dood is en het ontwaken een opwekking.', 'Said as soon as one opens one''s eyes, mindful that sleep is a minor death and waking a resurrection.', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الذكر وشكر نعمة الحياة.', 'Het beloont het openen van de dag met het gedenken van Allaah en de erkenning van de opwekking.', 'It rewards opening the day with the remembrance of Allaah and acknowledgement of the resurrection.', 'ما يقوله إذا استيقظ من نومه', 'tijdstip', 'time', 1, 1),('waking', 'time', '«الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ»', 'Alle lof zij Allaah, Die mijn lichaam gezond heeft gemaakt, mijn ziel aan mij heeft teruggegeven en mij heeft toegestaan Hem te gedenken.', 'All praise is for Allaah who gave my body wellbeing, returned my soul to me, and permitted me to remember Him.', 'يقوله عند الاستيقاظ، جامعا شكر ثلاث نعم: العافية، ورد الروح، والتوفيق للذكر.', 'Zegt men bij het ontwaken, drie gunsten dankend: de gezondheid, het teruggeven van de ziel en de toestemming tot dhikr.', 'Said upon waking, giving thanks for three favours: wellbeing, the return of the soul, and permission to remember Allaah.', 'لم يرد فيه أجر مخصوص، وأجره عموم فضل الحمد؛ و«الحمد لله تملأ الميزان» [مسلم (223)].', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'حمد العافية ورد الروح', 'tijdstip', 'time', 1, 2),('waking', 'time', '«لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ»', 'Niets of niemand heeft het recht aanbeden te worden behalve Allaah, alleen, zonder deelgenoot. Aan Hem behoort de heerschappij en aan Hem behoort alle lof, en Hij is tot alles in staat. Alle lof zij Allaah, verheven is Allaah, er is geen god behalve Allaah, Allaah is de Grootste, en er is geen macht noch kracht behalve bij Allaah. O Allaah, vergeef mij.', '', 'يقوله من انتبه من نومه في جوف الليل ولو لم يقم؛ فيبدأ بهذا الذكر ثم يدعو بما شاء، فإن أراد الكمال توضأ وصلى.', 'Zegt wie ''s nachts wakker wordt, ook al staat hij niet op; hij begint met deze dhikr en smeekt daarna.', 'Said by whoever wakes at night, even without rising; one begins with this dhikr then supplicates.', 'الأجر منصوص في الحديث: استجابة الدعاء، وقبول الصلاة إن توضأ وصلى.', 'De beloning staat in de hadieth: de verhoring van de smeekbede, en de aanvaarding van het gebed als hij woedoe verricht en bidt.', 'The reward is stated in the hadeeth: the answering of supplication, and the acceptance of prayer if he performs ablution and prays.', 'ما يقوله من تعارّ من', 'tijdstip', 'time', 1, 3),('waking', 'time', 'يبدأ بالسواك عند القيام من النوم مع ذكر الاستيقاظ المتقدم', 'Gebruik de siwaak bij het ontwaken uit de slaap, samen met de dhikr van het ontwaken.', 'Use the siwaak upon waking from sleep, together with the dhikr of waking.', 'يجمع المستيقظ بين ثلاث: مسح النوم عن وجهه بيده كما في حديث ابن عباس الآتي، وذكر الاستيقاظ بلسانه، والسواك لفمه؛ فيستقبل ذكر الله بنقاء الفم.', 'De ontwaakte combineert drie zaken: het wegvegen van de slaap met de hand, de dhikr en de siwaak.', 'The waker combines three things: wiping sleep from the face with the hand, the dhikr, and the siwaak.', 'لم يرد فيه أجر مخصوص هنا، وفي عمومه: «السواك مطهرة للفم مرضاة للرب» [النسائي (5)، وصححه الألباني].', 'Geen specifieke beloning hier; in het algemeen: ''de siwaak reinigt de mond en behaagt de Heer'' [an-Nasaa''ie 5, sahieh volgens al-Albaanie].', 'No specific reward here; in general: ''the siwaak purifies the mouth and pleases the Lord'' [an-Nasaa''ee 5, authenticated by al-Albaanee].', 'ومن هيئته ﷺ إذا قام من نومه: السواك', 'tijdstip', 'time', 1, 4),('waking', 'time', '﴿إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ ۝١٩٠ الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ۝١٩١ رَبَّنَا إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنْصَارٍ ۝١٩٢ رَبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ۝١٩٣ رَبَّنَا وَآتِنَا مَا وَعَدْتَنَا عَلَى رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ۝١٩٤ فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى بَعْضُكُمْ مِنْ بَعْضٍ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِنْ دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِنْ عِنْدِ اللَّهِ وَاللَّهُ عِنْدَهُ حُسْنُ الثَّوَابِ ۝١٩٥ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ۝١٩٦ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ ۝١٩٧ لَكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِنْ عِنْدِ اللَّهِ وَمَا عِنْدَ اللَّهِ خَيْرٌ لِلْأَبْرَارِ ۝١٩٨ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَنْ يُؤْمِنُ بِاللَّهِ وَمَا أُنْزِلَ إِلَيْكُمْ وَمَا أُنْزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَنًا قَلِيلًا أُولَئِكَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ ۝١٩٩ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾ [آل عمران: 190 ــ 200]', 'Waarlijk, in de schepping van de hemelen en de aarde en in de afwisseling van nacht en dag zijn tekenen voor de bezitters van verstand; degenen die Allaah gedenken staand, zittend en op hun zij liggend, en nadenken over de schepping van de hemelen en de aarde (zeggend): ''Onze Heer, U hebt dit niet voor niets geschapen. Heilig bent U, bescherm ons dus tegen de bestraffing van het Vuur. Onze Heer, wie U het Vuur binnenvoert, die hebt U te schande gemaakt, en voor de onrechtplegers zijn er geen helpers. Onze Heer, wij hoorden een oproeper oproepen tot het geloof: geloof in jullie Heer, en wij geloofden. Onze Heer, vergeef ons dus onze zonden, wis onze fouten uit en neem ons weg met de vromen. Onze Heer, geef ons wat U ons via Uw boodschappers hebt beloofd, en verneder ons niet op de Dag der Opstanding; voorwaar, U verbreekt de belofte niet.'' Hun Heer verhoorde hen toen: ''Ik doe het werk van geen enkele werker onder jullie verloren gaan, man of vrouw, jullie zijn uit elkaar voortgekomen. Degenen die uitweken, uit hun woningen verdreven werden, op Mijn weg gekwetst werden, en die streden en gedood werden: Ik zal zeker hun fouten uitwissen en hen zeker tuinen binnenvoeren waar rivieren onderdoor stromen, als beloning van bij Allaah; en bij Allaah is de goede beloning.'' Laat de vrije beweging van de ongelovigen door de landen je niet misleiden. Een geringe genieting; daarna is hun verblijfplaats de Hel, en dat is een slechte rustplaats. Maar voor degenen die hun Heer vrezen zijn er tuinen waar rivieren onderdoor stromen, daarin eeuwig levend, als een onthaal van bij Allaah; en wat bij Allaah is, is beter voor de vromen. En waarlijk, onder de Lieden van het Boek zijn er die in Allaah geloven en in wat naar jullie is neergezonden en wat naar hen is neergezonden, nederig voor Allaah; zij verkopen de tekenen van Allaah niet voor een geringe prijs. Zij zijn het voor wie er beloning is bij hun Heer; voorwaar, Allaah is snel in de afrekening. O jullie die geloven, wees geduldig, wees standvastig in geduld, wees paraat, en vrees Allaah, opdat jullie zullen slagen.', '', 'يقرؤها إذا استيقظ لقيام الليل، متدبرا وهو يمسح النوم عن وجهه، ثم يتوضأ ويصلي كما فعل صلى الله عليه وسلم.', 'Leest men bij het ontwaken voor het nachtgebed, mediterend terwijl men de slaap van het gezicht wist, waarna men de woedoe verricht en bidt zoals de Profeet (vrede en zegeningen zij met hem) deed.', 'Read upon waking for the night prayer, pondering while wiping sleep from the face, then performing ablution and praying as the Prophet (peace and blessings be upon him) did.', 'لم يرد فيها أجر مخصوص، وفيها الاقتداء الكامل بهديه صلى الله عليه وسلم في قيامه.', 'Geen specifieke beloning overgeleverd; het bevat de volledige navolging van zijn leidraad (vrede en zegeningen zij met hem) in het nachtgebed.', 'No specific reward reported; it contains full following of his guidance (peace and blessings be upon him) in the night prayer.', 'وكان ﷺ إذا استيقظ من', 'tijdstip', 'time', 1, 5),('night_prayer', 'time', '«اللَّهُمَّ رَبَّ جِبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ»', 'O Allaah, Heer van Djibraa''iel, Miekaa''iel en Israafiel, Schepper van de hemelen en de aarde, Kenner van het verborgene en het waarneembare: U oordeelt tussen Uw dienaren over datgene waarin zij verschilden. Leid mij, met Uw toestemming, naar de waarheid in hetgeen waarover men verschilt; waarlijk, U leidt wie U wilt naar een recht pad.', 'O Allaah, Lord of Djibriel, Meekaa''eel and Israafiel, Originator of the heavens and the earth, Knower of the unseen and the seen: You judge between Your servants concerning that in which they differed. Guide me, by Your leave, to the truth in that wherein they differ; indeed You guide whom You will to a straight path.', 'يقوله بعد تكبيرة الإحرام في قيام الليل قبل القراءة.', 'Zegt men na de openingstakbier in het nachtgebed, vóór de recitatie.', 'Said after the opening takbeer in the night prayer, before the recitation.', 'لم يرد فيه أجر مخصوص، وهو أنسب الاستفتاحات لطالب الهداية عند اختلاف الناس.', 'Geen specifieke beloning overgeleverd; het is de meest passende opening voor wie leiding zoekt te midden van meningsverschil.', 'No specific reward reported; it is the most fitting opening for one seeking guidance amid disagreement.', 'استفتاح صلاة الليل', 'tijdstip', 'time', 1, 6),('night_prayer', 'time', '«اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ لَكَ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ»', 'O Allaah, aan U alle lof: U bent de Onderhouder van de hemelen en de aarde en wie zich daarin bevinden. Aan U alle lof: aan U behoort de heerschappij van de hemelen en de aarde en wie zich daarin bevinden. Aan U alle lof: U bent het Licht van de hemelen en de aarde en wie zich daarin bevinden. Aan U alle lof: U bent de Waarheid, Uw belofte is waar, de ontmoeting met U is waar, Uw Woord is waar, het Paradijs is waar, het Vuur is waar, de profeten zijn waar, Muhammad (vrede en zegeningen zij met hem) is waar en het Uur is waar. O Allaah, aan U heb ik mij overgegeven, in U geloof ik, op U vertrouw ik, tot U keer ik terug, omwille van U twist ik en aan U leg ik het oordeel voor. Vergeef mij dus wat ik eerder deed en wat later kwam, wat ik verborg en wat ik openlijk deed. U bent Degene Die vooruit doet gaan en Degene Die uitstelt; er is geen god behalve U, en er is geen macht noch kracht behalve bij Allaah.', 'O Allaah, to You is all praise: You are the Sustainer of the heavens and the earth and all within them. To You is all praise: Yours is the dominion of the heavens and the earth and all within them. To You is all praise: You are the Light of the heavens and the earth and all within them. To You is all praise: You are the Truth, Your promise is true, the meeting with You is true, Your word is true, Paradise is true, the Fire is true, the prophets are true, Muhammad (peace and blessings be upon him) is true, and the Hour is true. O Allaah, to You I submit, in You I believe, upon You I rely, to You I turn, by You I contend, and to You I refer judgement. Forgive me what I have sent before and what I have left behind, what I concealed and what I declared. You are the One who brings forward and the One who delays; none has the right to be worshipped except You, and there is no might nor power except with Allaah.', 'يقوله في استفتاح تهجده، ويجوز الجمع بينه وبين استفتاح «اللهم رب جبرائيل» في ليال مختلفة إحياء للسنتين.', 'Zegt men bij de opening van zijn tahadjdjoed; men mag het op verschillende nachten afwisselen met de opening ''O Allaah, Heer van Djibriel''.', 'Said at the opening of one''s tahajjud; one may alternate it on different nights with the opening ''O Allaah, Lord of Jibreel''.', 'لم يرد فيه أجر مخصوص، وهو أعظم استفتاحات الثناء؛ جمع توحيد الربوبية والتفويض والاستغفار.', 'Geen specifieke beloning overgeleverd; het is de grootste lof-opening: het verenigt de tawhied van het Heerschap, de overgave en de istighfaar.', 'No specific reward reported; it is the greatest opening of praise: uniting the tawheed of Lordship, entrustment and seeking forgiveness.', 'دعاء التهجد', 'tijdstip', 'time', 1, 7),('night_prayer', 'time', 'يُكثر في الثلث الأخير من الدعاء والمسألة والاستغفار بما شاء؛ فليس فيه لفظ مؤقت', 'In het laatste derde deel van de nacht smeekt men veelvuldig, vraagt men en zoekt men vergeving; er is hiervoor geen vaste formule.', 'In the last third of the night one supplicates abundantly, asks and seeks forgiveness; no fixed wording is prescribed.', 'يتحرى الثلث الأخير من الليل فيجعله محل حاجاته الكبار وسؤاله واستغفاره.', 'Men zoekt het laatste derde van de nacht en maakt het tot de plaats van zijn grote behoeften, zijn vragen en zijn istighfaar.', 'One seeks the last third of the night and makes it the place of one''s great needs, requests and istighfaar.', 'الأجر منصوص: الاستجابة والإعطاء والمغفرة الموعودة في هذا الوقت.', 'De beloning is uitdrukkelijk: de verhoring, de gave en de beloofde vergeving op dit tijdstip.', 'The reward is stated: the answering, the giving and the promised forgiveness at this time.', 'ساعة النزول الإلهي', 'tijdstip', 'time', 1, 8),('friday', 'event', 'يتحرى الدعاء بما شاء؛ وأرجى أوقاتها آخر ساعة بعد العصر، وساعة الصلاة والخطبة', 'Men zoekt het uur van verhoring op vrijdag met smeekbeden naar keuze; het meest kansrijk is het laatste uur na het 3asr-gebed en het uur van de khutbah en het gebed.', 'One seeks the hour of response on Friday with any supplication; most likely is the last hour after 3asr and the time of the khutbah and prayer.', 'يجلس آخر ساعة من عصر الجمعة منتظرا المغرب ذاكرا داعيا؛ فمنتظر الصلاة في حكم المصلي.', 'Men zit het laatste uur van de vrijdagmiddag (3asr) in afwachting van de maghrib, gedenkend en smekend; wie op het gebed wacht, verkeert in de staat van de biddende.', 'One sits the last hour of Friday afternoon awaiting maghrib, remembering and supplicating; whoever awaits the prayer is in the state of one praying.', 'الأجر منصوص: لا يسأل الله فيها شيئا إلا أعطاه.', 'De beloning is uitdrukkelijk: hij vraagt Allaah daarin niets of Hij geeft het hem.', 'The reward is stated: he asks Allaah nothing therein but He gives it to him.', 'ساعة الإجابة', 'wekelijkse periode', 'weekly season', 1, 9),('friday', 'event', '«اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ» وَنَحْوُهُ مِنْ صِيَغِ الصَّلَاةِ الثَّابِتَةِ، يُكْثِرُ مِنْهَا يَوْمَ الْجُمُعَةِ وَلَيْلَتَهَا', 'O Allaah, schenk Uw gebeden en vrede aan onze Profeet Muhammad (veelvuldig op vrijdag).', 'O Allaah, send Your prayers and peace upon our Prophet Muhammad (abundantly on Friday).', 'يكثر منها يوم الجمعة بلا عدد مخصوص، وأكمل الصيغ الصلاة الإبراهيمية الواردة في التشهد.', 'Men vermeerdert het op vrijdag zonder vast aantal; de volledigste vorm is de Ibraahiem-zegening uit de tashahhoed.', 'One increases it on Friday without a fixed number; the fullest form is the Ibraaheemic blessing from the tashahhud.', '«فإن صلاتكم معروضة علي»، ومن صلى عليه واحدة صلى الله عليه بها عشرا [مسلم (384)].', '''Jullie zegeningen worden aan mij voorgelegd'', en wie eenmaal over hem zegent, over hem zegent Allaah tienmaal [Muslim 384].', '''Your blessings are presented to me'', and whoever blesses him once, Allaah blesses him tenfold [Muslim 384].', 'الإكثار من الصلاة على النبي ﷺ يومها', 'wekelijkse periode', 'weekly season', 1, 10),('friday', 'event', 'قراءة سورة الكهف كاملة في يومها أو ليلتها', 'Het reciteren van soerah al-Kahf in zijn geheel op de dag of de nacht van vrijdag.', 'Reciting soorah al-Kahf in full on Friday or its night.', 'يقرؤها من غروب شمس الخميس إلى غروب شمس الجمعة.', 'Men leest haar van zonsondergang op donderdag tot zonsondergang op vrijdag.', 'One reads it from sunset on Thursday to sunset on Friday.', 'الأجر منصوص: نور ما بين الجمعتين.', 'De beloning is uitdrukkelijk: licht tussen de twee vrijdagen.', 'The reward is stated: light between the two Fridays.', 'وقراءة سورة الكهف يوم الجمعة', 'wekelijkse periode', 'weekly season', 1, 11),('new_moon', 'event', '«اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيمَانِ، وَالسَّلَامَةِ وَالْإِسْلَامِ، [وَالتَّوْفِيقِ لِمَا تُحِبُّ وَتَرْضَى: مِنْ رِوَايَةِ ابْنِ عُمَرَ]، رَبِّي وَرَبُّكَ اللَّهُ»', 'Allaah is de Grootste. O Allaah, laat deze maan over ons verschijnen met zegen en geloof, met veiligheid en islam [en met de leiding tot wat U liefheeft en waarover U tevreden bent]. Mijn Heer en jouw Heer is Allaah.', 'Allaah is the Greatest. O Allaah, bring this crescent over us with blessing and faith, with safety and Islam [and with success in what You love and are pleased with]. My Lord and your Lord is Allaah.', 'يقوله من رأى الهلال بعينه أول الشهر، ولا يُشرع تكلف ترائيه لأجل الذكر، ومن لم يره فلا يقوله على الخبر.', 'Zegt wie de nieuwe maan met eigen oog ziet aan het begin van de maand; het is niet voorgeschreven zich in te spannen haar te zien omwille van de dhikr, en wie haar niet ziet, zegt het niet.', 'Said by whoever sees the crescent with his own eye at the month''s start; one is not to strain to sight it for the sake of the dhikr, and whoever does not see it does not say it.', 'لم يرد فيه أجر مخصوص، وفيه استقبال الشهر بالتيمن والدعاء.', 'Geen specifieke beloning overgeleverd; het bevat het verwelkomen van de maand met een goed voorteken en smeekbede.', 'No specific reward reported; it contains greeting the month with a good omen and supplication.', 'ما يقوله إذا رأى الهلال', 'maandelijkse periode', 'monthly season', 1, 12),('morning', 'time', '﴿فَاصْبِرْ عَلَى مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ﴾', 'Vertaling van de betekenis: Wees dus geduldig met wat zij zeggen, en prijs de lof van jouw Heer vóór zonsopgang en vóór zonsondergang [Qaaf 39] — de basis van de adhkaar van de twee dagdelen.', 'Meaning: So be patient with what they say, and glorify the praise of your Lord before sunrise and before sunset [Qaaf 39] — the basis of the morning and evening adhkaar.', 'فقبل طلوع الشمس وقت أذكار الصباح، وقبل الغروب وقت أذكار المساء؛ ففيها امتثال هذا الأمر القرآني كل يوم.', 'Vóór zonsopgang is de tijd van de ochtend-adhkaar en vóór zonsondergang die van de avond-adhkaar; daarin ligt de dagelijkse uitvoering van dit Koran-gebod.', 'Before sunrise is the time of the morning adhkaar and before sunset that of the evening adhkaar; in them lies the daily fulfilment of this Qur''anic command.', '', 'Het beloont het dagelijks uitvoeren van het Koran-gebod tot gedenken bij dageraad en avond.', 'It rewards the daily fulfilment of the Qur''anic command to remember Allaah at dawn and evening.', 'آية الصبر والتسبيح طرفي النهار', 'tijdstip', 'time', 1, 13),('morning', 'time', '﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا ۝٤١ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا﴾', 'Vertaling van de betekenis: O jullie die geloven, gedenk Allaah veelvuldig, en prijs Hem in de ochtend en de late namiddag [al-Ahzaab 41-42].', 'Meaning: O you who believe, remember Allaah with much remembrance, and glorify Him morning and late afternoon [al-Ahzaab 41-42].', 'فالبكرة أول النهار والأصيل آخره، وهما محل هذه الأذكار.', 'De ochtend is het begin van de dag en de namiddag het einde ervan; beide zijn de tijd van deze adhkaar.', 'The morning is the start of the day and the late afternoon its end; both are the time of these adhkaar.', '', '', '', 'آية ذكر الله كثيرا', 'tijdstip', 'time', 1, 14),('morning', 'time', 'الجلوس للذكر من الفجر إلى الشروق ومن العصر إلى الغروب', 'Het zitten in dhikr van fadjr tot zonsopgang en van 3asr tot zonsondergang; de Profeet (vrede en zegeningen zij met hem) achtte elk van beide zittingen geliefder dan het vrijlaten van vier slaven.', 'Sitting in remembrance from fajr until sunrise and from asr until sunset; each sitting was dearer to the Prophet (peace and blessings be upon him) than freeing four slaves.', 'أفضل تطبيق للقسمين: مجلس ذكر بعد الفجر حتى الشروق وبعد العصر إلى الغروب.', 'De beste uitvoering van beide delen: een dhikr-zitting na fadjr tot zonsopgang en na 3asr tot zonsondergang.', 'The best performance of both parts: a dhikr sitting after fajr until sunrise and after 3asr until sunset.', 'الأجر منصوص: كل جلسة أحب إلى النبي صلى الله عليه وسلم من عتق أربع رقاب من ولد إسماعيل.', 'Elke van beide zittingen was de Profeet (vrede en zegeningen zij met hem) liefteer dan het vrijlaten van vier slaven.', 'Each of the two sittings was dearer to the Prophet (peace and blessings be upon him) than freeing four slaves.', 'فضل مجلس الذكر طرفي النهار', 'tijdstip', 'time', 1, 15),('morning', 'time', '﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ [البقرة: 255]', 'Allaah, er is geen god dan Hij, de Levende, de Onderhouder van al het bestaande. Sluimer noch slaap kan Hem treffen. Aan Hem behoort wat in de hemelen en op de aarde is. Wie is degene die bij Hem kan bemiddelen zonder Zijn toestemming? Hij kent wat voor hen is en wat achter hen is, en zij kunnen niets van Zijn kennis omvatten, behalve wat Hij wil. Zijn Zetel (Kursie) omvat de hemelen en de aarde, en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Geweldige.', '', 'تقرأ مرة واحدة حين يصبح ومرة حين يمسي.', 'Wordt eenmaal gelezen in de ochtend en eenmaal in de avond.', 'Read once in the morning and once in the evening.', 'الأجر منصوص: من قالها حين يصبح أُجير من الجن حتى يمسي، ومن قالها حين يمسي أُجير منهم حتى يصبح.', 'De beloning is uitdrukkelijk: wie het in de ochtend zegt is tegen de djinn beschermd tot de avond, en wie het in de avond zegt tot de ochtend.', 'The reward is stated: whoever says it in the morning is protected from the jinn until evening, and whoever says it in the evening until morning.', 'آية الكرسي', 'tijdstip', 'time', 1, 16),('morning', 'time', '﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ و﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ و﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾', 'Vertaling van de betekenis: soerah al-Ikhlaas (de zuivere toewijding), soerah al-Falaq (de dageraad) en soerah an-Naas (de mensen) — de drie beschermende soewar, volledig gereciteerd.', 'Meaning: soorah al-Ikhlaas, soorah al-Falaq and soorah an-Naas — the three protective chapters, recited in full.', 'تقرأ السور الثلاث ثلاثا حين يصبح وثلاثا حين يمسي.', 'De drie soewar worden driemaal in de ochtend en driemaal in de avond gelezen.', 'The three soorahs are read three times in the morning and three times in the evening.', 'الأجر منصوص: «تكفيك من كل شيء».', 'De beloning is uitdrukkelijk: ''zij volstaat je tegen alles''.', 'The reward is stated: ''it suffices you against everything''.', 'سورة الإخلاص والمعوذتان في الصباح', 'tijdstip', 'time', 1, 17),('morning', 'time', '«أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ»', 'Wij zijn de ochtend ingegaan en de heerschappij behoort Allaah toe, en alle lof zij Allaah. Er is geen god behalve Allaah, alleen, zonder deelgenoot; aan Hem behoort de heerschappij en de lof, en Hij is tot alles in staat. Mijn Heer, ik vraag U het goede van deze dag en het goede van wat erna komt, en ik zoek toevlucht bij U tegen het kwade van deze dag en het kwade van wat erna komt. Mijn Heer, ik zoek toevlucht bij U tegen luiheid en de ellende van de ouderdom. Mijn Heer, ik zoek toevlucht bij U tegen een bestraffing in het Vuur en een bestraffing in het graf.', 'We have entered the morning and the dominion belongs to Allaah, and all praise is for Allaah. None has the right to be worshipped except Allaah alone, without partner; His is the dominion and His is the praise, and He is able to do all things. My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from the evil of this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the misery of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.', 'يقال مرة إذا أصبح، ونظيره بلفظ الليلة إذا أمسى.', 'Eenmaal gezegd in de ochtend, en zijn tegenhanger met de bewoording ''nacht'' in de avond.', 'Said once in the morning, and its counterpart with the wording ''night'' in the evening.', 'لم يرد فيه أجر مخصوص، وهو من أجمع الأذكار لسؤال خير اليوم والاستعاذة من شره.', 'Geen specifieke beloning overgeleverd; het is een van de meest omvattende adhkaar voor het vragen van het goede van de dag en toevlucht tegen het kwade ervan.', 'No specific reward reported; it is among the most comprehensive adhkaar for asking the good of the day and refuge from its evil.', 'ذكر الملك لله إذا أصبح', 'tijdstip', 'time', 1, 18),('morning', 'time', '«اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ»', 'O Allaah, met U zijn wij de ochtend ingegaan en met U de avond, met U leven wij en met U sterven wij, en tot U is de opwekking.', 'O Allaah, by You we enter the morning and by You we enter the evening; by You we live and by You we die, and to You is the resurrection.', 'يقال مرة إذا أصبح، ويقال بلفظ المصير إذا أمسى.', 'Eenmaal gezegd in de ochtend, en met de bewoording ''terugkeer'' (al-masier) in de avond.', 'Said once in the morning, and with the wording ''return'' (al-maseer) in the evening.', 'لم يرد فيه أجر مخصوص، وفيه تفويض الطرفين والمحيا والممات إلى الله.', 'Geen specifieke beloning overgeleverd; het bevat de overgave van de beide dagdelen, het leven en de dood aan Allaah.', 'No specific reward reported; it contains entrusting the two ends of the day, life and death, to Allaah.', 'الاعتصام بالله في اليوم كله', 'tijdstip', 'time', 1, 19),('morning', 'time', '«اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ»', 'O Allaah, U bent mijn Heer, er is geen god dan U. U hebt mij geschapen en ik ben Uw dienaar, en ik houd mij aan Uw verbond en Uw belofte zoveel als ik kan. Ik zoek toevlucht bij U tegen het kwaad dat ik heb verricht. Ik erken Uw gunst aan mij en ik erken mijn zonde, dus vergeef mij, want niemand vergeeft de zonden behalve U.', '', 'يقال مرة في النهار ومرة في الليل بيقين قلب واستحضار معنى.', 'Eenmaal overdag en eenmaal ''s nachts gezegd, met overtuiging van hart en besef van de betekenis.', 'Said once by day and once by night, with conviction of heart and awareness of the meaning.', 'الأجر منصوص: من قاله موقنا به فمات في يومه أو ليلته فهو من أهل الجنة.', 'De beloning is uitdrukkelijk: wie het overtuigd zegt en die dag of nacht sterft, behoort tot de mensen van het Paradijs.', 'The reward is stated: whoever says it with conviction and dies that day or night is among the people of Paradise.', 'سيد الاستغفار', 'tijdstip', 'time', 1, 20);